Action: run_sql({'query': "SELECT \n    ek.slchd_establishment_key,\n    COALESCE(e.name, ek.name) as name,\n    COUNT(i.inspection_id) as total_inspections,\n    MIN(i.inspection_date) as earliest_date,\n    MAX(i.inspection_date) as latest_date\nFROM establishment_keys ek\nJOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nLEFT JOIN establishments e ON ek.slchd_establishment_key = e.slchd_establishment_key\nWHERE i.inspection_date >= '2021-07-17'\nGROUP BY ek.slchd_establishment_key, COALESCE(e.name, ek.name)\nHAVING COUNT(i.inspection_id) >= 2\nORDER BY total_inspections DESC\nLIMIT 20;"})

