Action: run_sql({'query': "WITH insp_crit AS (\n    SELECT \n        i.inspection_id,\n        i.slchd_establishment_key,\n        i.inspection_date,\n        YEAR(i.inspection_date) as insp_year,\n        COUNT(CASE WHEN vc.critical THEN 1 END) as critical_count\n    FROM inspections i\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2021-01-01'\n    GROUP BY i.inspection_id, i.slchd_establishment_key, i.inspection_date\n),\nperiod_stats AS (\n    SELECT \n        slchd_establishment_key,\n        -- Early period: 2021 - 2023\n        COUNT(CASE WHEN insp_year BETWEEN 2021 AND 2023 THEN 1 END) as early_inspections,\n        SUM(CASE WHEN insp_year BETWEEN 2021 AND 2023 THEN critical_count ELSE 0 END) as early_criticals,\n        AVG(CASE WHEN insp_year BETWEEN 2021 AND 2023 THEN critical_count END) as early_avg_crit,\n        -- Late period: 2024 - 2026\n        COUNT(CASE WHEN insp_year BETWEEN 2024 AND 2026 THEN 1 END) as late_inspections,\n        SUM(CASE WHEN insp_year BETWEEN 2024 AND 2026 THEN critical_count ELSE 0 END) as late_criticals,\n        AVG(CASE WHEN insp_year BETWEEN 2024 AND 2026 THEN critical_count END) as late_avg_crit\n    FROM insp_crit\n    GROUP BY slchd_establishment_key\n)\nSELECT \n    ek.name,\n    ps.slchd_establishment_key,\n    ps.early_inspections,\n    ps.early_criticals,\n    ROUND(ps.early_avg_crit, 2) as early_avg_crit,\n    ps.late_inspections,\n    ps.late_criticals,\n    ROUND(ps.late_avg_crit, 2) as late_avg_crit,\n    ROUND(ps.late_avg_crit - ps.early_avg_crit, 2) as avg_crit_change\nFROM period_stats ps\nJOIN establishment_keys ek ON ps.slchd_establishment_key = ek.slchd_establishment_key\nWHERE ps.early_inspections > 0 AND ps.late_inspections > 0\nORDER BY avg_crit_change DESC\nLIMIT 15;"})

