Action: run_sql({'query': "WITH insp_crit AS (\n    SELECT \n        i.inspection_id,\n        i.slchd_establishment_key,\n        i.inspection_date,\n        YEAR(i.inspection_date) as insp_year,\n        COUNT(CASE WHEN vc.critical THEN 1 END) as critical_count\n    FROM inspections i\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE i.inspection_date >= '2021-01-01'\n    GROUP BY i.inspection_id, i.slchd_establishment_key, i.inspection_date\n),\nperiod_stats AS (\n    SELECT \n        slchd_establishment_key,\n        COUNT(CASE WHEN insp_year BETWEEN 2021 AND 2023 THEN 1 END) as early_inspections,\n        AVG(CASE WHEN insp_year BETWEEN 2021 AND 2023 THEN critical_count END) as early_avg_crit,\n        COUNT(CASE WHEN insp_year BETWEEN 2024 AND 2026 THEN 1 END) as late_inspections,\n        AVG(CASE WHEN insp_year BETWEEN 2024 AND 2026 THEN critical_count END) as late_avg_crit\n    FROM insp_crit\n    GROUP BY slchd_establishment_key\n),\nchanges AS (\n    SELECT \n        slchd_establishment_key,\n        early_avg_crit,\n        late_avg_crit,\n        late_avg_crit - early_avg_crit as diff,\n        CASE \n            WHEN late_avg_crit - early_avg_crit > 0 THEN 'Increased'\n            WHEN late_avg_crit - early_avg_crit < 0 THEN 'Decreased'\n            ELSE 'Unchanged'\n        END as trend_category\n    FROM period_stats\n    WHERE early_inspections > 0 AND late_inspections > 0\n)\nSELECT \n    trend_category,\n    COUNT(*) as establishment_count,\n    ROUND(COUNT(*) * 100.0 / SUM(COUNT(*)) OVER (), 1) as pct\nFROM changes\nGROUP BY trend_category\nORDER BY establishment_count DESC;"})

